def transform(grid):
    h, w = len(grid), len(grid[0])

    # The divider is a uniform row or column with equally sized panels on either side.
    divider = None
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)) and c == w - 1 - c:
            divider = ("col", c)
            break
    if divider is None:
        for r in range(h):
            if all(x == grid[r][0] for x in grid[r]) and r == h - 1 - r:
                divider = ("row", r)
                break

    if divider[0] == "col":
        c = divider[1]
        a = [row[:c] for row in grid]
        b = [row[c + 1:] for row in grid]
    else:
        r = divider[1]
        a, b = grid[:r], grid[r + 1:]

    shared = set(x for row in a for x in row) & set(x for row in b for x in row)
    color = next(iter(shared))
    return [
        [3 if a[i][j] == color and b[i][j] == color else color
         for j in range(len(a[0]))]
        for i in range(len(a))
    ]
